h,w=15,28
grid=[[1]*w for _ in range(h)]
markers=[[5,11,16,20,24],[2,8],[5,11,25],[1,14],[4,9,23],[1,12,19,26],[4],[1,9,15,23],[4,20,26],[9,13,23],[1,17],[6,11,20,26],[3,23],[6,10,16,20,26],[2,13,23]]
for r,cs in enumerate(markers):
    for c in cs:grid[r][c]=5
for c in (17,18,19):grid[2][c]=8
out=[row[:] for row in grid]
for r,cs in enumerate(markers):
    for c in cs:
        for cc in range(max(0,c-1),min(w,c+2)):
            out[r][cc]=8
import json
print(json.dumps({'action':'submit','grid':out},separators=(',',':')))

